mapper.select:
select  from marketing_channel_voucher
where account_id = #{accountId}
and create_time >= #{from}
and create_time < #{to}
order by id desc limit #{limit}

mapper.update:
update marketing_channel_voucher
set status = 2, revoke_source = #{source}, update_time = #{updateTime}
where id = #{id} and status in (0, 1)

update marketing_channel_voucher
set inventory_state = 2, update_time = #{updateTime}
where id = #{id} and inventory_state = 1

update marketing_channel_voucher
set inventory_state = 3, update_time = #{updateTime}
where id = #{id} and inventory_state in (1, 2)
